#include <vector>
#include <algorithm>

class Solution {
public:
    long long maxAlternatingSubsequenceSum(std::vector<int>& nums, int k) {
        int n = nums.size();
        if (n == 0) return 0;
        std::vector<long long> dpValley(n), dpPeak(n);
        long long ans = nums[0];
        for (int i = 0; i < n; ++i) {
            dpValley[i] = nums[i];
            dpPeak[i] = nums[i];
            ans = std::max(ans, (long long)nums[i]);
            for (int j = 0; j <= i - k; ++j) {
                if (nums[j] > nums[i]) {
                    dpValley[i] = std::max(dpValley[i], nums[i] + dpPeak[j]);
                }
                if (nums[j] < nums[i]) {
                    dpPeak[i] = std::max(dpPeak[i], nums[i] + dpValley[j]);
                }
            }
            ans = std::max({ans, dpValley[i], dpPeak[i]});
        }
        return ans;
    }
};

class Solution {
    public long maxAlternatingSubsequenceSum(int[] nums, int k) {
        int n = nums.length;
        if (n == 0) return 0;
        long[] dpValley = new long[n];
        long[] dpPeak = new long[n];
        long ans = nums[0];
        for (int i = 0; i < n; i++) {
            dpValley[i] = nums[i];
            dpPeak[i] = nums[i];
            ans = Math.max(ans, nums[i]);
            for (int j = 0; j <= i - k; j++) {
                if (nums[j] > nums[i]) {
                    dpValley[i] = Math.max(dpValley[i], nums[i] + dpPeak[j]);
                }
                if (nums[j] < nums[i]) {
                    dpPeak[i] = Math.max(dpPeak[i], nums[i] + dpValley[j]);
                }
            }
            ans = Math.max(ans, Math.max(dpValley[i], dpPeak[i]));
        }
        return ans;
    }
}

